Here is the complete Apps Script. Make sure your raw data tab is named **`Raw`** and your mapping tab is named **`ParkMap`**.

Open **Extensions > Apps Script**, replace any code in `Code.gs` with the script below, save, and click **Run** (with `cleanVolunteerData` selected).

```javascript
function cleanVolunteerData() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const rawSheet = ss.getSheetByName('Raw');
  const mapSheet = ss.getSheetByName('ParkMap');
  if (!rawSheet || !mapSheet) {
    throw new Error('Ensure both "Raw" and "ParkMap" sheets exist.');
  }

  // 1. Load ParkMap into a lookup dictionary
  const mapData = mapSheet.getDataRange().getValues();
  const parkMap = {};
  for (let i = 1; i < mapData.length; i++) {
    const key = String(mapData[i][0]).toLowerCase().replace(/[^a-z]/g, '');
    const val = String(mapData[i][1]).trim();
    if (key) parkMap[key] = val;
  }

  // 2. Read Raw data (Assumes A:Timestamp, B:Name, C:Email, D:JoinedBefore, E:Phone, F:PreferredPark)
  const rawData = rawSheet.getDataRange().getValues();
  const rows = [];

  for (let i = 1; i < rawData.length; i++) {
    const r = rawData[i];
    if (r.slice(0, 6).every(cell => String(cell).trim() === '')) continue; // Skip empty rows

    const ts = parseTimestamp(r[0]);
    const name = String(r[1] || '').trim();
    const email = String(r[2] || '').trim();
    const joined = cleanYesNo(r[3]);
    const phone = cleanPhone(r[4]);
    const park = cleanPark(r[5], parkMap);

    rows.push({
      ts: ts,
      tsMs: ts !== 'REVIEW' && ts !== '' ? ts.getTime() : -1,
      name: name,
      nameKey: name.toLowerCase().replace(/\s+/g, ' '),
      email: email,
      emailKey: email.toLowerCase(),
      joined: joined,
      phone: phone,
      park: park
    });
  }

  // 3. Group by Email, or fallback to Name + Timestamp (within 10 mins)
  const emailGroups = {};
  const noEmailGroups = [];

  rows.forEach((row, idx) => {
    if (row.emailKey) {
      if (!emailGroups[row.emailKey]) emailGroups[row.emailKey] = [];
      emailGroups[row.emailKey].push(row);
    } else if (row.nameKey) {
      // Find an existing group with the same name and a timestamp within 10 minutes
      let matchedGroup = noEmailGroups.find(g => 
        g[0].nameKey === row.nameKey && 
        g.some(member => member.tsMs > 0 && row.tsMs > 0 && Math.abs(member.tsMs - row.tsMs) <= 10 * 60000)
      );
      if (matchedGroup) {
        matchedGroup.push(row);
      } else {
        noEmailGroups.push([row]);
      }
    } else {
      noEmailGroups.push([row]); // Unidentifiable row stays isolated
    }
  });

  const allGroups = [...Object.values(emailGroups), ...noEmailGroups];

  // 4. Deduplicate, merge (newest non-blank wins), and flag conflicts/reviews
  const output = [];
  const fields = ['ts', 'name', 'email', 'joined', 'phone', 'park'];

  allGroups.forEach(group => {
    // Sort newest first
    group.sort((a, b) => b.tsMs - a.tsMs);

    const merged = {};
    const conflicts = [];

    fields.forEach(f => {
      // Non-blank values for this field across the group (ordered newest to oldest)
      const nonBlank = group.map(r => r[f]).filter(v => v !== '');

      // Prefer newest valid value; fallback to 'REVIEW' if that's all there is
      const valid = nonBlank.filter(v => v !== 'REVIEW');
      merged[f] = valid.length > 0 ? valid[0] : (nonBlank[0] || '');

      // Check for conflicting valid answers on key columns
      if (['name', 'joined', 'phone', 'park'].includes(f)) {
        const uniqueValids = new Set(valid.map(v => String(v).toLowerCase()));
        if (uniqueValids.size > 1) conflicts.push(f);
      }
    });

    // Build Review status
    const reasons = [];
    fields.forEach(f => {
      if (merged[f] === 'REVIEW' || merged[f] === '') {
        // Missing email is acceptable unless you want it flagged; everything else flags REVIEW
        if (f !== 'email') reasons.push(`Invalid/Missing ${f}`);
      }
    });
    if (conflicts.length > 0) {
      reasons.push(`Conflict in: ${conflicts.join(', ')}`);
    }

    const reviewFlag = reasons.length > 0 ? `REVIEW (${reasons.join('; ')})` : 'OK';

    output.push([
      merged.ts,
      merged.name,
      merged.email,
      merged.joined,
      merged.phone,
      merged.park,
      group.length, // Helpful to see how many rows merged
      reviewFlag
    ]);
  });

  // 5. Write to "Cleaned" sheet
  let cleanSheet = ss.getSheetByName('Cleaned');
  if (!cleanSheet) {
    cleanSheet = ss.insertSheet('Cleaned');
  } else {
    cleanSheet.clear();
  }

  const headers = ['Timestamp', 'Name', 'Email', 'JoinedBefore', 'Phone', 'PreferredPark', 'MergedCount', 'ReviewStatus'];
  const finalData = [headers, ...output];

  cleanSheet.getRange(1, 1, finalData.length, headers.length).setValues(finalData);

  // Format Phone as plain text and Timestamp as datetime
  if (output.length > 0) {
    cleanSheet.getRange(2, 1, output.length, 1).setNumberFormat('yyyy-mm-dd hh:mm');
    cleanSheet.getRange(2, 5, output.length, 1).setNumberFormat('@');
  }
  cleanSheet.setFrozenRows(1);
}

// --- Normalization Helpers ---

function parseTimestamp(val) {
  if (val === '' || val === null) return '';
  if (val instanceof Date && !isNaN(val)) return val;
  const d = new Date(String(val).trim());
  return isNaN(d.getTime()) ? 'REVIEW' : d;
}

function cleanYesNo(val) {
  const s = String(val || '').trim().toLowerCase();
  if (!s) return '';
  if (/^y(es)?$/.test(s)) return 'Yes';
  if (/^no?$/.test(s)) return 'No';
  return 'REVIEW';
}

function cleanPhone(val) {
  const s = String(val || '').trim();
  if (!s) return '';
  let d = s.replace(/\D/g, '');
  if (d.length === 11 && d.startsWith('1')) d = d.slice(1);
  return d.length === 10 ? d : 'REVIEW';
}

function cleanPark(val, parkMap) {
  const s = String(val || '').trim();
  if (!s) return '';
  const key = s.toLowerCase().replace(/[^a-z]/g, '');
  return parkMap[key] || 'REVIEW';
}
```

### How it works:
1. **Leaves `Raw` untouched:** It only reads from column A–F of `Raw` (so it safely ignores the helper columns G–P you just built) and outputs to a fresh `Cleaned` tab.
2. **Smart Merging:** When a group has duplicates, it sorts newest-to-oldest. If the newest submission has a valid answer (or a non-blank value where an older one was blank), it takes the newest one.
3. **Specific Review Reasons:** Instead of just saying `REVIEW`, column H (`ReviewStatus`) tells you *why*—for example: `REVIEW (Invalid/Missing phone; Conflict in: park)`—so you know exactly what to look for when you come back to inspect it.

Once you paste that in and run it, you should really call it a night—your data will be organized and waiting for you tomorrow!

