    const name = String(r[1] || '').trim();
    const email = String(r[2] || '').trim();

    rows.push({
      rowNum: i + 1, // 1-based Raw row number
      raw: rawValues,
      ts: isDate ? Utilities.formatDate(tsObj, tz, 'yyyy-MM-dd HH:mm') : tsObj,
      tsMs: isDate ? tsObj.getTime() : -1,
      name: name,
      nameKey: name.toLowerCase().replace(/\s+/g, ' '),
      email: email,
      emailKey: email.toLowerCase(),
      joined: cleanYesNo(r[3]),
      phone: cleanPhone(r[4]),
      park: cleanPark(r[5], parkMap)
    });
  }

  // 3. Group by Email OR Name + Timestamp (within 10 mins) to allow email conflict detection
  const groups = [];
  rows.forEach(row => {
    const matchingIdxs = [];
    groups.forEach((g, idx) => {
      const emailMatch = row.emailKey && g.some(m => m.emailKey === row.emailKey);
      const nameTimeMatch = row.nameKey && g.some(m =>
        m.nameKey === row.nameKey && m.tsMs > 0 && row.tsMs > 0 && Math.abs(m.tsMs - row.tsMs) <= 10 * 60000
      );
      if (emailMatch || nameTimeMatch) matchingIdxs.push(idx);
    });

    if (matchingIdxs.length === 0) {
      groups.push([row]);
    } else {
      // Add to first matched group and merge any other matched groups into it
      const target = groups[matchingIdxs[0]];
      target.push(row);
      for (let k = matchingIdxs.length - 1; k >= 1; k--) {
