  const output = [];
  const fields = ['ts', 'name', 'email', 'joined', 'phone', 'park'];
  let reviewedCount = 0;
  let extraMergedRows = 0;

  groups.forEach(group => {
    // Sort newest first (tie-break by newest row number)
    group.sort((a, b) => (b.tsMs - a.tsMs) || (b.rowNum - a.rowNum));

    if (group.length > 1) extraMergedRows += (group.length - 1);
    const sourceRows = group.map(r => r.rowNum).sort((a, b) => a - b).join(',');
    const newestRaw = group[0].raw;

    const merged = {};
    const conflicts = [];

