// Adds custom menu when the spreadsheet opens
function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu('Data Cleaning')
    .addItem('Clean Data', 'cleanVolunteerData')
    .addToUi();
}

function cleanVolunteerData() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const tz = ss.getSpreadsheetTimeZone();
  const rawSheet = ss.getSheetByName('Raw');
  const mapSheet = ss.getSheetByName('ParkMap');
  if (!rawSheet || !mapSheet) {
    throw new Error('Ensure both "Raw" and "ParkMap" sheets exist.');
  }

  // 1. Load ParkMap into a lookup dictionary & collect canonical park names
  const mapData = mapSheet.getDataRange().getValues();
  const parkMap = {};
  const canonicalParks = new Set();
  for (let i = 1; i < mapData.length; i++) {
    const key = String(mapData[i][0]).toLowerCase().replace(/[^a-z]/g, '');
    const val = String(mapData[i][1]).trim();
    if (key && val) {
      parkMap[key] = val;
      canonicalParks.add(val);
    }
  }

  // 2. Read Raw data and preserve original row numbers & raw A:F values
  const rawData = rawSheet.getDataRange().getValues();
  const rows = [];

  for (let i = 1; i < rawData.length; i++) {
    const r = rawData[i].slice(0, 6);
    if (r.every(cell => String(cell).trim() === '')) continue; // Skip empty rows

    const tsObj = parseTimestamp(r[0]);
    const isDate = tsObj instanceof Date;
    const rawValues = r.map(c => (c instanceof Date && !isNaN(c)) ? Utilities.formatDate(c, tz, 'yyyy-MM-dd HH:mm') : String(c));

    const name = String(r[1] || '').trim();
    const email = String(r[2] || '').trim();

    rows.push({
      rowNum: i + 1,
      raw: rawValues,
      ts: isDate ? Utilities.formatDate(tsObj, tz, 'yyyy-MM-dd HH:mm') : 'REVIEW',
      tsMs: isDate ? tsObj.getTime() : -1,
      name: name,
      nameKey: name.toLowerCase().replace(/\s+/g, ' '),
      email: email,
      emailKey: email.toLowerCase(),
      joined: cleanYesNo(r[3]),
      phone: cleanPhone(r[4]),
      park: cleanPark(r[5], parkMap)
    });
  }

  // 3. Group by Email OR Name + Timestamp (within 10 mins)
  const groups = [];
  rows.forEach(row => {
    const matchingIdxs = [];
    groups.forEach((g, idx) => {
      const emailMatch = row.emailKey && g.some(m => m.emailKey === row.emailKey);
      const nameTimeMatch = row.nameKey && g.some(m =>
        m.nameKey === row.nameKey && m.tsMs > 0 && row.tsMs > 0 && Math.abs(m.tsMs - row.tsMs) <= 10 * 60000
      );
      if (emailMatch || nameTimeMatch) matchingIdxs.push(idx);
    });

    if (matchingIdxs.length === 0) {
      groups.push([row]);
    } else {
      const target = groups[matchingIdxs[0]];
      target.push(row);
      for (let k = matchingIdxs.length - 1; k >= 1; k--) {
        target.push(...groups[matchingIdxs[k]]);
        groups.splice(matchingIdxs[k], 1);
      }
    }
  });

  // 4. Deduplicate, merge (newest non-blank wins), and track counts
  const output = [];
  const fields = ['ts', 'name', 'email', 'joined', 'phone', 'park'];
  let reviewedCount = 0;
  let extraMergedRows = 0;

  // Initialize park counts (OK groups by canonical park + REVIEW/Unknown)
  const parkCounts = {};
  canonicalParks.forEach(p => parkCounts[p] = 0);
  let unknownParkCount = 0;

  groups.forEach(group => {
    group.sort((a, b) => (b.tsMs - a.tsMs) || (b.rowNum - a.rowNum));

    if (group.length > 1) extraMergedRows += (group.length - 1);
    const sourceRows = group.map(r => r.rowNum).sort((a, b) => a - b).join(',');
    const newestRaw = group[0].raw;

    const merged = {};
    const conflicts = [];
    let emailsFound = '';

    fields.forEach(f => {
      const nonBlank = group.map(r => r[f]).filter(v => v !== '');
      const valid = nonBlank.filter(v => v !== 'REVIEW');
      merged[f] = valid.length > 0 ? valid[0] : (nonBlank[0] || '');

      if (f === 'email') {
        const uniqueEmails = [...new Set(valid.map(v => v.toLowerCase()))];
        emailsFound = uniqueEmails.join(', ');
        if (uniqueEmails.length > 1) {
          conflicts.push(`email (${uniqueEmails.join(', ')})`);
        }
      } else if (['name', 'joined', 'phone', 'park'].includes(f)) {
        const uniqueValids = new Set(valid.map(v => String(v).toLowerCase()));
        if (uniqueValids.size > 1) conflicts.push(f);
      }
    });

    if (!merged.ts || merged.ts === 'REVIEW') merged.ts = 'REVIEW';

    const phoneFormatted = /^\d{10}$/.test(merged.phone)
      ? `(${merged.phone.slice(0, 3)}) ${merged.phone.slice(3, 6)}-${merged.phone.slice(6)}`
      : merged.phone;

    const reasons = [];
    fields.forEach(f => {
      if (merged[f] === 'REVIEW' || (merged[f] === '' && f !== 'email')) {
        reasons.push(`Invalid/Missing ${f}`);
      }
    });
    if (conflicts.length > 0) {
      reasons.push(`Conflict in: ${conflicts.join(', ')}`);
    }

    const isReview = reasons.length > 0;
    if (isReview) reviewedCount++;
    const reviewFlag = isReview ? `REVIEW (${reasons.join('; ')})` : 'OK';

    // Tally park breakdown: count OK groups by canonical park; unmapped/review parks go to REVIEW/Unknown
    if (!merged.park || merged.park === 'REVIEW') {
      unknownParkCount++;
    } else if (!isReview) {
      parkCounts[merged.park] = (parkCounts[merged.park] || 0) + 1;
    }

    output.push([
      merged.ts,
      merged.name,
      merged.email,
      emailsFound,
      merged.joined,
      merged.phone,
      phoneFormatted,
      merged.park,
      sourceRows,
      group.length,
      reviewFlag,
      ...newestRaw
    ]);
  });

  // 5. Build Summary Block (Side-by-side: Overall in Cols A-B, Park Breakdown in Cols D-E)
  const headers = [
    'Timestamp', 'Name', 'Email', 'EmailsFound', 'JoinedBefore', 'Phone', 'PhoneFormatted', 'PreferredPark',
    'SourceRows', 'MergedCount', 'ReviewStatus',
    'Raw_Timestamp', 'Raw_Name', 'Raw_Email', 'Raw_JoinedBefore', 'Raw_Phone', 'Raw_PreferredPark'
  ];

  const leftSummary = [
    ['Total Groups', groups.length],
    ['Reviewed Groups', reviewedCount],
    ['Merged Duplicate Rows', extraMergedRows]
  ];

  const rightSummary = [
    ...Object.entries(parkCounts).map(([park, count]) => [`${park} (OK)`, count]),
    ['REVIEW/Unknown Park', unknownParkCount]
  ];

  const summaryHeight = Math.max(leftSummary.length, rightSummary.length);
  const summaryRows = [];
  for (let i = 0; i < summaryHeight; i++) {
    const row = new Array(headers.length).fill('');
    if (i < leftSummary.length) {
      row[0] = leftSummary[i][0];
      row[1] = leftSummary[i][1];
    }
    if (i < rightSummary.length) {
      row[3] = rightSummary[i][0]; // Col D
      row[4] = rightSummary[i][1]; // Col E
    }
    summaryRows.push(row);
  }

  // 6. Write Summary, Headers, and Data to "Cleaned"
  let cleanSheet = ss.getSheetByName('Cleaned');
  if (!cleanSheet) {
    cleanSheet = ss.insertSheet('Cleaned');
  } else {
    cleanSheet.clear();
  }

  const headerRowIdx = summaryHeight + 1;
  const dataStartRow = headerRowIdx + 1;
  const finalGrid = [...summaryRows, headers, ...output];
  const targetRange = cleanSheet.getRange(1, 1, finalGrid.length, headers.length);

  // Format key columns as plain text BEFORE writing values
  if (output.length > 0) {
    cleanSheet.getRange(dataStartRow, 1, output.length, 1).setNumberFormat('@');  // Cleaned Timestamp
    cleanSheet.getRange(dataStartRow, 6, output.length, 2).setNumberFormat('@');  // Phone & PhoneFormatted
    cleanSheet.getRange(dataStartRow, 9, output.length, 1).setNumberFormat('@');  // SourceRows
    cleanSheet.getRange(dataStartRow, 12, output.length, 6).setNumberFormat('@'); // Raw A:F
  }

  targetRange.setValues(finalGrid);
  cleanSheet.getRange(1, 1, headerRowIdx, headers.length).setFontWeight('bold');
  cleanSheet.setFrozenRows(headerRowIdx);
}

// --- Normalization Helpers ---

function parseTimestamp(val) {
  if (val === '' || val === null) return 'REVIEW';
  if (val instanceof Date && !isNaN(val)) return val;
  const d = new Date(String(val).trim());
  return isNaN(d.getTime()) ? 'REVIEW' : d;
}

function cleanYesNo(val) {
  const s = String(val || '').trim().toLowerCase();
  if (!s) return '';
  if (/^y(es)?$/.test(s)) return 'Yes';
  if (/^no?$/.test(s)) return 'No';
  return 'REVIEW';
}

function cleanPhone(val) {
  const s = String(val || '').trim();
  if (!s) return '';
  let d = s.replace(/\D/g, '');
  if (d.length === 11 && d.startsWith('1')) d = d.slice(1);
  return d.length === 10 ? d : 'REVIEW';
}

function cleanPark(val, parkMap) {
  const s = String(val || '').trim();
  if (!s) return '';
  const key = s.toLowerCase().replace(/[^a-z]/g, '');
  return parkMap[key] || 'REVIEW';
}
```

### Layout Note:
Because the number of canonical parks in `ParkMap` might grow over time, the script puts the overall summary in **Columns A–B** and the park breakdown right next to it in **Columns D–E**, and automatically adjusts the header row and frozen rows to sit right below whichever summary list is taller.

